float sphere(vec3 ray_pos, vec3 sph_pos, float sph_r)
{
    return distance(ray_pos, sph_pos) - sph_r;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 pos = vec3 (uv, 0);
    vec3 cam_pos = vec3 (0, 0, -2);
    vec3 dir = normalize(pos - cam_pos);

    vec3 col = vec3(0, 0, 0);

    float c_dist = 0.0;
    float dotPro = 0.0;

    vec3 spherePosition = vec3 ((iMouse.xy/iResolution.xy * 2.0 - 1.0).xyy + vec3 (0, 0, 1.5));

    if (iMouse.xy == vec2(0))
    {
        spherePosition = vec3 (0.0, 0.0, 0.5);
    }


    float sphereRadius = 0.5;

    for (int i = 1; i <= 10; i++)
    {
        c_dist = sphere(pos, spherePosition, sphereRadius);

        if(c_dist <= 0.01)
        {
            dotPro = dot(dir, normalize(spherePosition - pos));
            //col = vec3(1, 1, 1) * (dotPro);
            col = vec3(normalize(spherePosition - pos) + vec3 (0.2, 0.2, 0));
            break;
        }

        pos = pos + (dir * c_dist);
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
